SELECT

FROM document_archive

    deleted = 0

        AND project_id = #{param.projectId}


        AND document_no LIKE CONCAT('%', #{param.documentNo}, '%')


        AND document_name LIKE CONCAT('%', #{param.documentName}, '%')


        AND document_type = #{param.documentType}


        AND document_category LIKE CONCAT('%', #{param.documentCategory}, '%')


        AND file_format = #{param.fileFormat}


        AND archiver_id = #{param.archiverId}


        AND access_level = #{param.accessLevel}


        AND document_status = #{param.documentStatus}


        AND (keywords LIKE CONCAT('%', #{param.keywords}, '%')
        OR document_name LIKE CONCAT('%', #{param.keywords}, '%')
        OR document_summary LIKE CONCAT('%', #{param.keywords}, '%'))


        AND archive_date >= #{param.archiveDateStart}


        AND archive_date <= #{param.archiveDateEnd}


        AND create_time >= #{param.createTimeStart}


        AND create_time <= #{param.createTimeEnd}


ORDER BY ${param.orderBySql}

SELECT COUNT(1)
FROM document_archive


        AND project_id = #{param.projectId}


        AND document_type = #{param.documentType}


        AND document_status = #{param.documentStatus}

mapper.delete:
DELETE FROM document_archive
WHERE id IN

    #{id}

mapper.update:
UPDATE document_archive
SET document_status = #{status}, update_time = SYSDATE
WHERE id = #{id}
